forum.content_text:
MCU STM32H503KBU

internal clock  64 MHz

During a UART restart,

the HAL\_UART\_Init function calls

HAL\_RCCEx\_PeriphCLKConfig, which results in a HardFault\_Handler

```

void UART_Set_BaudRate(UART_HandleTypeDef *huart, uint32_t BaudRate)

{

if (HAL_UART_DeInit(huart)!= HAL_OK)

{

Error_Handler();

}

huart->Instance = USART1;

huart->Init.BaudRate = BaudRate;

huart->Init.WordLength = UART_WORDLENGTH_8B;

huart->Init.StopBits = UART_STOPBITS_1;

huart->Init.Parity = UART_PARITY_NONE;

huart->Init.Mode = UART_MODE_TX_RX;

huart->Init.HwFlowCtl = UART_HWCONTROL_NONE;

huart->Init.OverSampling = UART_OVERSAMPLING_16;

huart->Init.OneBitSampling = UART_ONE_BIT_SAMPLE_DISABLE;

huart->Init.ClockPrescaler = UART_PRESCALER_DIV1;

huart->AdvancedInit.AdvFeatureInit = UART_ADVFEATURE_NO_INIT;

if (HAL_UART_Init(huart) != HAL_OK)

{

Error_Handler();

}

if (HAL_UART_Receive_IT( OW.huart, &uart_temp, 1) != HAL_OK)

Error_Handler();

}

```

If you disable the HAL\_UART\_DeInit function, everything works.

What could be the problem?
